alter table public.relationships drop constraint relationships_relationship_type_check;
alter table public.relationships add constraint relationships_relationship_type_check check(relationship_type in
 ('covered_by','certified_against','applies_to','approved_for','affects_component','references','supersedes'));

create function public.review_pa28_batch5_graph() returns integer
language plpgsql security definer set search_path=pg_catalog,public as $$
declare item jsonb; reference jsonb; v uuid; source_id uuid; model_id uuid; ref_id uuid; model_name text; count_rows integer:=0;
begin
 perform pg_advisory_xact_lock(hashtextextended('review-pa28-batch5',0));
 for item in select value from jsonb_array_elements($review$[
  {"type":"AD","number":"2005-01-19","hash":"ebceaed478eb1c0c84226c633f6556ae98a1800d9974cecb44f758986994b74f","models":["PA-28-140","PA-28-181"],"page":7,"excerpt":"The Piper row on page 7 lists PA-28-140 and PA-28-181. Paragraph (c) on page 5 limits applicability to installed Garmin GTX 33, 33D, 330 or 330D transponders with specified software versions.","conditions":{"equipment_key":"GARMIN:GTX33-33D-330-330D","equipment_scope":"Installed Garmin GTX 33, GTX 33D, GTX 330 or GTX 330D with software 3.00, 3.01, 3.02, 3.04 or 3.05. Equipment-family installation alone does not establish the installed software version.","software":"Page 9 states that previously installed version 3.03 requires no further action and that the AD does not apply to versions later than 3.05.","compliance":"Profile equipment is user reported. Software version, completed upgrade and aircraft records require review."},"references":[{"authority":"GARMIN","kind":"appliance_model","key":"GARMIN:GTX33-33D-330-330D","label":"Garmin GTX 33/33D/330/330D Mode S transponders","relationship":"affects_component","page":5,"excerpt":"Paragraph (c) identifies the four installed Garmin Mode S transponder models and affected software versions.","conditions":{"part_scope":"GTX 33, GTX 33D, GTX 330 and GTX 330D; applicability also depends on software version."}},{"authority":"FAA","kind":"certificate","key":"AD:2004-10-15","label":"AD 2004-10-15","relationship":"supersedes","page":5,"excerpt":"Paragraph (b) states that AD 2005-01-19 supersedes AD 2004-10-15, Amendment 39-13645.","conditions":{"reference_role":"Superseded AD identified in the current original; its full original was not reviewed in this batch."}},{"authority":"GARMIN","key":"MSB:0304:B:2003-06-12","label":"Garmin Mandatory Software Service Bulletin 0304 Rev B - June 12, 2003","page":10,"excerpt":"Paragraph (g) incorporates Garmin Mandatory Software Service Bulletin 0304, Revision B, dated June 12, 2003, for software upgrade 3.03.","conditions":{"reference_role":"One of two bulletin paths named by the AD. Bulletin text was not retrieved."}},{"authority":"GARMIN","key":"MSB:0409:2004-07-19","label":"Garmin Mandatory Software Service Bulletin 0409 - July 19, 2004","page":10,"excerpt":"Paragraph (g) incorporates Garmin Mandatory Software Service Bulletin 0409, dated July 19, 2004, for software upgrade 3.06.","conditions":{"reference_role":"One of two bulletin paths named by the AD. Bulletin text was not retrieved."}}]},
  {"type":"AD","number":"2006-03-08","hash":"afb93197ba8601823bd0df8afb97f405462408dc25843fdc4298aa3fd66d6872","models":["PA-28-140","PA-28-181"],"page":7,"excerpt":"The Piper row on page 7 lists PA-28-140 and PA-28-181. Paragraph (c) on page 6 limits applicability to installed Aero Advantage ADV200 vacuum pump part numbers ADV211CC and ADV212CW.","conditions":{"equipment_key":"AERO-ADVANTAGE:ADV211CC-ADV212CW","equipment_scope":"Installed ADV200 series vacuum pump P/N ADV211CC or ADV212CW. Installation may be under STC SA10126SC, field approval or another method; the aircraft list is not exclusive.","compliance":"Profile equipment is user reported. Pump identity, removal, replacement, monitoring-system configuration and records require review."},"references":[{"authority":"AERO-ADVANTAGE","kind":"appliance_model","key":"AERO-ADVANTAGE:ADV211CC-ADV212CW","label":"Aero Advantage ADV200 vacuum pumps ADV211CC/ADV212CW","relationship":"affects_component","page":6,"excerpt":"Paragraph (c) identifies ADV200 vacuum pump part numbers ADV211CC and ADV212CW as the affected equipment.","conditions":{"part_scope":"ADV211CC or ADV212CW installed; the listed aircraft and approval routes are not exhaustive."}},{"authority":"FAA","kind":"certificate","key":"STC:SA10126SC","label":"STC SA10126SC","page":6,"excerpt":"Paragraph (c) identifies STC SA10126SC as one possible installation route, along with field approval or other methods.","conditions":{"reference_role":"Possible installation route only. The AD is not limited to installations under this STC, and installation on an individual aircraft is not established."}},{"authority":"PHOENIX-GROUP","key":"SB:05-01:2005-11-22","label":"Phoenix Group SB 05-01 - November 22, 2005","page":9,"excerpt":"Paragraph (g) incorporates Phoenix Group Service Bulletin 05-01, dated November 22, 2005, when the replacement pump monitoring system is retained.","conditions":{"reference_role":"Conditional monitoring-system instructions. Bulletin text was not retrieved."}}]},
  {"type":"AD","number":"2005-25-08","hash":"1331eaaad4b2632cab64dfe7dc5b6ad345556c96f09eef64bd5881be8e3dcea0","models":["PA-28-181"],"page":5,"excerpt":"Paragraph (c) and its table list PA-28-181, all serial numbers, only when an affected Shadin ADC-2000 part number in configuration B, C or D is installed.","conditions":{"equipment_key":"SHADIN:ADC2000-962830A-S8","equipment_scope":"Installed Shadin ADC-2000 P/N 962830A-1-S-8, 962830A-2-S-8 or 962830A-3-S-8, configuration B, C or D. The PA-28-181 model row alone is insufficient.","compliance":"Profile equipment is user reported. Part number, configuration, modification status, preflight checks and aircraft records require review."},"references":[{"authority":"SHADIN","kind":"appliance_model","key":"SHADIN:ADC2000-962830A-S8","label":"Shadin ADC-2000 962830A-1/-2/-3-S-8","relationship":"affects_component","page":5,"excerpt":"Paragraph (c) identifies three ADC-2000 part numbers in configurations B, C and D as the affected equipment.","conditions":{"part_scope":"P/N 962830A-1-S-8, -2-S-8 or -3-S-8 in configuration B, C or D."}},{"authority":"SHADIN","key":"SB:SB28-05-002:C:2005-06-29","label":"Shadin SB28-05-002 Rev C - June 29, 2005","page":6,"excerpt":"Paragraph (g) incorporates Shadin Service Bulletin SB28-05-002, Revision C, dated June 29, 2005.","conditions":{"reference_role":"AD-cited modification and interim-procedure bulletin. Bulletin text was not retrieved."}}]},
  {"type":"AD","number":"2006-12-07","hash":"0e779f27e83c4818168ca39ce36f01326bfd91a49194c3c1b6e58aab3cae480c","models":["PA-28-140"],"page":7,"excerpt":"Table 2 on page 7 lists the PA-28 140 with an O-320-E2A engine. Paragraph (c) on page 4 requires an applicable Lycoming parallel-valve engine with a specified ECi Classic Cast cylinder part, marking and serial range installed.","conditions":{"equipment_key":"ECI:AEL65102-CLASSIC-CAST","equipment_scope":"Installed ECi AEL65102 series Classic Cast cylinder assembly with head marking EC 65099-REV-1 and cylinder serial 1 through 9879; an L prefix is allowed. Applicability also requires a Table 1 Lycoming 320/360/540 parallel-valve engine.","aircraft_table":"Table 2 says engines are installed on, but not limited to, the listed aircraft. The PA-28 140 row does not prove that an affected engine or cylinder is installed.","compliance":"Profile equipment is user reported. Engine model, cylinder part/marking/serial, replacement status and maintenance records require review."},"references":[{"authority":"ECI","kind":"appliance_model","key":"ECI:AEL65102-CLASSIC-CAST","label":"ECi AEL65102 Classic Cast cylinder assemblies","relationship":"affects_component","page":4,"excerpt":"Paragraph (c) identifies AEL65102 series Classic Cast cylinders with marking EC 65099-REV-1 and serials 1 through 9879.","conditions":{"part_scope":"Affected cylinder identity requires part series, casting head marking and cylinder serial range."}},{"authority":"LYCOMING","kind":"engine_model","key":"LYCOMING:320-360-540-PARALLEL-VALVE","label":"Lycoming 320/360/540 parallel-valve engine families","relationship":"affects_component","page":4,"excerpt":"Paragraph (c) and Table 1 restrict applicability to specified Lycoming 320, 360 and 540 parallel-valve engine models.","conditions":{"reference_role":"Engine-family predicate combined with the affected ECi cylinder identity; engine installation alone is insufficient."}},{"authority":"FAA","kind":"certificate","key":"AD:2005-26-10","label":"AD 2005-26-10","relationship":"supersedes","page":4,"excerpt":"Paragraph (b) states that AD 2006-12-07 supersedes AD 2005-26-10, Amendment 39-14431.","conditions":{"reference_role":"Superseded AD identified in the current original; the replacement corrects applicability tables and the casting part number."}},{"authority":"ECI","key":"SB:05-08:2:2006-02-28","label":"ECi SB 05-08 Revision 2 - February 28, 2006","page":14,"excerpt":"Related Information paragraph (k) states that ECi Service Bulletin 05-08, Revision 2, dated February 28, 2006, pertains to the subject of the AD.","conditions":{"reference_role":"Related information, not identified here as incorporated by reference. Bulletin text was not retrieved."}}]}
 ]$review$::jsonb) loop
  select dv.id into v from public.document_versions dv join public.documents d on d.id=dv.document_id
   where d.authority='FAA' and d.document_type='AD' and d.document_number=item->>'number' and dv.content_sha256=item->>'hash'
    and dv.status='current' and dv.is_published and d.is_published and exists(select 1 from public.related_document_matches match where match.version_id=dv.id and match.is_active) limit 1;
  if v is null then raise exception 'Verified current original missing'; end if;
  insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published) values('FAA','certificate','AD:'||(item->>'number'),'AD '||(item->>'number'),true)
   on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into source_id;
  for model_name in select jsonb_array_elements_text(item->'models') loop
   select id into model_id from public.catalog_entities where authority='FAA' and entity_type='aircraft_model' and natural_key=model_name;
   if model_id is null or not exists(select 1 from public.related_document_matches where version_id=v and model=model_name and is_active) then raise exception 'Current model index missing'; end if;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,model_id,'applies_to',v,(item->>'page')::integer,item->>'excerpt',item->'conditions','reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=model_id and evidence_version_id=v and relationship_type='applies_to');
   count_rows:=count_rows+1;
  end loop;
  for reference in select value from jsonb_array_elements(item->'references') loop
   insert into public.catalog_entities(authority,entity_type,natural_key,label,is_published)
    values(reference->>'authority',coalesce(reference->>'kind','service_document'),reference->>'key',reference->>'label',true)
    on conflict(authority,entity_type,natural_key) do update set is_published=true returning id into ref_id;
   insert into public.relationships(source_entity_id,target_entity_id,relationship_type,evidence_version_id,evidence_page,evidence_excerpt,applicability_conditions,review_status,is_published)
    select source_id,ref_id,coalesce(reference->>'relationship','references'),v,(reference->>'page')::integer,reference->>'excerpt',reference->'conditions','reviewed',true
    where not exists(select 1 from public.relationships where source_entity_id=source_id and target_entity_id=ref_id and evidence_version_id=v and relationship_type=coalesce(reference->>'relationship','references'));
   count_rows:=count_rows+1;
  end loop;
 end loop;
 return count_rows;
end $$;
revoke all on function public.review_pa28_batch5_graph() from public,anon,authenticated;
grant execute on function public.review_pa28_batch5_graph() to service_role;

create or replace view public.model_graph with(security_invoker=true) as
select r.id,d.document_number as tcds_number,s.label as model,t.label as target,t.entity_type as target_type,
  r.relationship_type,r.evidence_page,r.evidence_excerpt,r.applicability_conditions,v.revision_label as evidence_revision,v.source_url,
  d.document_number as source_document_number,d.document_type as source_document_type,t.natural_key as basis_key,
  null::text as path_via,'outgoing'::text as direction,v.id as evidence_version_id,
  s.id as source_entity_id,t.id as target_entity_id,s.id as model_entity_id,null::uuid as via_entity_id,r.evidence_attachment_id,a.file_name as evidence_file_name,v.metadata->>'original_source_url' as original_source_url
from public.relationships r join public.catalog_entities s on s.id=r.source_entity_id join public.catalog_entities t on t.id=r.target_entity_id
join public.document_versions v on v.id=r.evidence_version_id join public.documents d on d.id=v.document_id left join public.source_attachments a on a.id=r.evidence_attachment_id
where r.review_status='reviewed' and r.is_published and v.is_published and d.is_published and s.is_published and t.is_published and s.entity_type='aircraft_model' and d.authority='FAA' and d.document_type='TCDS' and v.id=d.current_version_id and (r.evidence_attachment_id is null or a.is_active)
union all
select r.id,'2A13',t.label,s.label,s.entity_type,r.relationship_type,r.evidence_page,r.evidence_excerpt,r.applicability_conditions,v.revision_label,v.source_url,
  d.document_number,d.document_type,s.natural_key,null::text,'incoming'::text,v.id,s.id,t.id,t.id,null::uuid,r.evidence_attachment_id,a.file_name,v.metadata->>'original_source_url'
from public.relationships r join public.catalog_entities s on s.id=r.source_entity_id join public.catalog_entities t on t.id=r.target_entity_id
join public.document_versions v on v.id=r.evidence_version_id join public.documents d on d.id=v.document_id left join public.source_attachments a on a.id=r.evidence_attachment_id
where r.review_status='reviewed' and r.is_published and v.is_published and d.is_published and s.is_published and t.is_published and t.entity_type='aircraft_model' and d.authority='FAA' and d.document_type in('AD','STC') and v.status='current' and (r.evidence_attachment_id is null or a.is_active)
  and exists(select 1 from public.related_document_matches m where m.version_id=v.id and m.model=t.label and m.is_active)
union all
select r.id,'2A13',m.label,t.label,t.entity_type,r.relationship_type,r.evidence_page,r.evidence_excerpt,r.applicability_conditions,v.revision_label,v.source_url,
  d.document_number,d.document_type,t.natural_key,s.label,'outgoing'::text,v.id,s.id,t.id,m.id,s.id,r.evidence_attachment_id,a.file_name,v.metadata->>'original_source_url'
from public.relationships r join public.catalog_entities s on s.id=r.source_entity_id join public.catalog_entities t on t.id=r.target_entity_id
join public.document_versions v on v.id=r.evidence_version_id join public.documents d on d.id=v.document_id left join public.source_attachments a on a.id=r.evidence_attachment_id
join public.relationships scope on scope.source_entity_id=s.id and scope.evidence_version_id=v.id and scope.relationship_type in('applies_to','approved_for')
join public.catalog_entities m on m.id=scope.target_entity_id and m.entity_type='aircraft_model'
where r.review_status='reviewed' and r.is_published and v.is_published and d.is_published and s.is_published and t.is_published and scope.review_status='reviewed' and scope.is_published and m.is_published and r.relationship_type in('affects_component','references','supersedes') and d.authority='FAA' and d.document_type in('AD','STC') and v.status='current' and (r.evidence_attachment_id is null or a.is_active)
  and (scope.evidence_attachment_id is null or exists(select 1 from public.source_attachments sa where sa.id=scope.evidence_attachment_id and sa.is_active))
  and exists(select 1 from public.related_document_matches active where active.version_id=v.id and active.model=m.label and active.is_active);
